<style>
  .detail-loading{width:min(1180px,calc(100% - 36px));margin:28px auto 70px;color:#667873}.detail-loading__crumb{width:210px;height:13px;border-radius:8px;background:#e6eeeb;margin-bottom:20px}.detail-loading__grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:28px}.detail-loading article,.detail-loading aside>div{background:#fff;border:1px solid #deebe6;border-radius:14px}.detail-loading article{padding:35px}.detail-loading article>span{display:block;width:92px;height:22px;border-radius:7px;background:#dcece6}.detail-loading h1{height:48px;width:78%;border-radius:10px;background:#e7efec;margin:18px 0 12px}.detail-loading p{height:15px;width:88%;border-radius:8px;background:#edf3f1;margin:12px 0}.detail-loading__hero{height:340px;border-radius:12px;background:linear-gradient(90deg,#e4eeea,#f6f9f8,#e4eeea);background-size:200% 100%;animation:detailPulse 1.35s infinite;margin:28px 0}.detail-loading aside{display:grid;gap:17px}.detail-loading aside>div{height:145px;background:linear-gradient(90deg,#f5f8f7,#e8f0ed,#f5f8f7);background-size:200% 100%;animation:detailPulse 1.35s infinite}.detail-loading>strong{display:block;text-align:center;margin-top:18px;font-size:11px}@keyframes detailPulse{to{background-position:-200% 0}}@media(max-width:780px){.detail-loading__grid{grid-template-columns:1fr}.detail-loading aside{display:none}.detail-loading article{padding:22px}.detail-loading__hero{height:230px}}
</style>